// Find candidates in Assessment/Review whose Last Contacted is 3+ days ago.
const zone = 'America/Vancouver';
const today = DateTime.now().setZone(zone).startOf('day');

function getField(row, name) {
  const key = Object.keys(row).find(k => k.trim().toLowerCase() === name.toLowerCase());
  return key === undefined ? undefined : row[key];
}

function parseDate(v) {
  if (v === undefined || v === null || v === '') return null;
  if (typeof v === 'number') {
    // Google Sheets serial date (days since 1899-12-30)
    return DateTime.fromObject({ year: 1899, month: 12, day: 30 }, { zone }).plus({ days: Math.floor(v) });
  }
  const s = String(v).trim();
  const formats = ['yyyy-MM-dd', 'yyyy-MM-dd HH:mm:ss', 'M/d/yyyy', 'M/d/yyyy H:mm:ss', 'd/M/yyyy'];
  let d = DateTime.fromISO(s, { zone });
  for (const f of formats) {
    if (d.isValid) break;
    d = DateTime.fromFormat(s, f, { zone });
  }
  return d.isValid ? d.startOf('day') : null;
}

const waiting = [];
for (const item of $input.all()) {
  const row = item.json;
  const stage = String(getField(row, 'Stage') || '').trim();
  if (!['assessment', 'review'].includes(stage.toLowerCase())) continue;
  const last = parseDate(getField(row, 'Last Contacted'));
  if (!last) continue;
  const days = Math.floor(today.diff(last, 'days').days);
  if (days < 3) continue;
  const score = getField(row, 'Score');
  waiting.push({
    name: String(getField(row, 'Candidate Name') || getField(row, 'Name') || '(no name)').trim(),
    stage,
    score: score === undefined || score === '' ? 'n/a' : score,
    days,
  });
}

if (waiting.length === 0) return [];

waiting.sort((a, b) => b.days - a.days);
const lines = waiting.map((c, i) => (i + 1) + '. ' + c.name + ' | Stage: ' + c.stage + ' | Score: ' + c.score + ' | Days since last contact: ' + c.days);
const body = waiting.length + ' candidate(s) are waiting on a follow-up (Assessment or Review, last contacted 3+ days ago):\n\n' + lines.join('\n');

return [{ json: { count: waiting.length, candidates: waiting, body } }];
